# Cloudflare Workers static assets: response headers for the site.
# https://developers.cloudflare.com/workers/static-assets/headers/
#
# The app is a single-purpose Workers site with no third-party script: the only
# cross-origin resources are swisstopo tiles/images and e-rara IIIF images, and
# every fetch goes through the same-origin /api/* Worker proxy.

/*
  X-Content-Type-Options: nosniff
  Referrer-Policy: strict-origin-when-cross-origin
  X-Frame-Options: SAMEORIGIN
  Permissions-Policy: geolocation=(), camera=(), microphone=(), payment=()
  Content-Security-Policy: default-src 'self'; base-uri 'self'; form-action 'self'; frame-ancestors 'self'; object-src 'none'; script-src 'self'; style-src 'self' 'unsafe-inline'; font-src 'self'; img-src 'self' data: blob: https://www.e-rara.ch https://wmts.geo.admin.ch https://api3.geo.admin.ch https://map.geo.admin.ch; connect-src 'self'

# Fonts never change under the same file name: cache them hard.
/fonts/*
  Cache-Control: public, max-age=31536000, immutable

# App code and styles change during development: short cache, revalidate often.
/app/*
  Cache-Control: public, max-age=300
/styles/*
  Cache-Control: public, max-age=300

# Data files are regenerated by scripts/harvest-seed.mjs: keep them fresh.
/data/*
  Cache-Control: public, max-age=600
====
/**
 * JSON from an allowlisted upstream (IIIF manifest, image service `info.json`).
 *
 * The site ships a strict `connect-src 'self'` CSP (public/_headers), so the
 * same-origin Worker proxy (`/api/fetch`, edge-cached, host allowlist) is the
 * *primary* path — it is also what keeps the e-rara/other collections usable
 * when their CORS headers change. The direct call stays as a fallback for a
 * deployment without the Worker (e.g. plain static hosting): e-rara sends
 * `access-control-allow-origin: *` (verified 2026-10-18, see docs/data-sources.md).
 *
 * The error message keeps both attempts' raw text (for logs/tests);
 * `describeUpstreamError` in iiif.js is what turns it into a sentence a visitor
 * can act on. No other module should re-implement this ladder.
 */
export async function fetchUpstreamJson(url) {
  try {
    const res = await fetch(`/api/fetch?url=${encodeURIComponent(url)}&accept=application/json`);
    if (!res.ok) throw new Error(`Proxy HTTP ${res.status}`);
    return await res.json();
  } catch (proxyError) {
    try {
      const res = await fetch(url, { headers: { accept: 'application/json' } });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      return await res.json();
    } catch (directError) {
      throw new Error(`${proxyError.message} / ${directError.message}`);
    }
  }
}

#!/usr/bin/env node
/**
 * Headless browser smoke check (development tool, not part of the build).
 *
 * Uses the Chromium binary on the runner and the DevTools protocol via Node's
 * built-in WebSocket – no npm dependencies. Collects console errors, failed
 * requests and a DOM snapshot, then writes a screenshot.
 *
 *   node scripts/browser-smoke.mjs [url] [--out /tmp/shot.png] [--wait 8000]
 */
import { spawn } from 'node:child_process';
import { writeFile, mkdtemp } from 'node:fs/promises';
