#!/usr/bin/env node
// Edge-case probe for the integrated Kartenzeit app (throwaway, /tmp only).
import { spawn } from 'node:child_process';
import { mkdtemp } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';

const BASE = process.argv[2] ?? 'http://127.0.0.1:8787';
const port = 9444;
const binary = ['/usr/bin/chromium', '/usr/bin/chromium-browser', '/usr/bin/google-chrome'].find(Boolean);
const userDataDir = await mkdtemp(path.join(tmpdir(), 'cdp-probe-'));
const child = spawn(binary, [
  '--headless=new', `--remote-debugging-port=${port}`, `--user-data-dir=${userDataDir}`,
  '--no-sandbox', '--disable-gpu', '--hide-scrollbars', '--window-size=1440,1000', 'about:blank',
], { stdio: ['ignore', 'ignore', 'pipe'] });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function endpoint(p) {
  for (let i = 0; i < 40; i += 1) {
    try { const res = await fetch(`http://127.0.0.1:${port}${p}`); if (res.ok) return res.json(); } catch {}
    await sleep(250);
  }
  throw new Error(`CDP ${p} not reachable`);
}
await endpoint('/json/version');
const target = await fetch(`http://127.0.0.1:${port}/json/new?about:blank`, { method: 'PUT' }).then((r) => r.json());
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
let id = 0;
const pending = new Map();
let events = [];
ws.onmessage = (m) => {
  const d = JSON.parse(m.data);
  if (d.id && pending.has(d.id)) { pending.get(d.id)(d); pending.delete(d.id); }
  else if (d.method) events.push(d);
};
const send = (method, params = {}) => new Promise((resolve) => {
  const mid = ++id; pending.set(mid, resolve); ws.send(JSON.stringify({ id: mid, method, params }));
});
const evalJs = async (expr) => {
  const r = await send('Runtime.evaluate', { expression: expr, returnByValue: true, awaitPromise: true });
  if (r.result?.exceptionDetails) return { __error: r.result.exceptionDetails.text, detail: r.result.exceptionDetails.exception?.description };
  return r.result?.result?.value;
};
await send('Runtime.enable');
await send('Log.enable');
await send('Page.enable');
await send('Console.enable').catch(() => {});

async function probe(name, url, waitFor = 'document.querySelectorAll("#result-list > *").length > 0', timeout = 15000) {
  events = [];
  await send('Page.navigate', { url });
  const t0 = Date.now();
  let ok = false;
  while (Date.now() - t0 < timeout) {
    try { const v = await evalJs(waitFor); if (v) { ok = true; break; } } catch {}
    await sleep(250);
  }
  await sleep(900);
  const consoleErrors = events
    .filter((e) => e.method === 'Runtime.consoleAPICalled' && e.params.type === 'error')
    .map((e) => e.params.args.map((a) => a.value ?? a.description).join(' ').slice(0, 220));
  const exceptions = events
    .filter((e) => e.method === 'Runtime.exceptionThrown')
    .map((e) => e.params.exceptionDetails.text + ' ' + (e.params.exceptionDetails.exception?.description ?? '')).slice(0, 220);
  const state = await evalJs(`(() => ({
    url: location.href.replace(location.origin, ''),
    count: document.querySelector('#result-count')?.textContent?.trim().slice(0, 90) ?? null,
    rows: document.querySelectorAll('#result-list > *').length,
    sel: document.querySelector('[data-detail]')?.hidden === false || document.querySelector('#detail-panel')?.hidden === false,
    bodyHasImg: document.body.innerHTML.includes('onerror'),
    xss: window.__xss === true,
    cmpPanes: document.querySelectorAll('[data-compare-pane]').length,
    notices: document.querySelector('#app-notices')?.textContent?.trim().slice(0, 120) ?? null,
    overflow: document.documentElement.scrollWidth - document.documentElement.clientWidth,
    mapMarkers: document.querySelectorAll('.map-marker').length,
  }))()`);
  return { name, waited: ok, consoleErrors, exceptions, state };
}

const cases = [
  ['inverted range', `${BASE}/?from=1900&to=1546`],
  ['junk params', `${BASE}/?from=abc&to=xyz&at=nan,nan&vv=9999999,1,2,3&cvv=garbage&cmp=unknown:1&sel=unknown:9&z=99999&lat=999&lon=999`],
  ['xss query', `${BASE}/?q=%3Cimg%20src%3Dx%20onerror%3Dwindow.__xss%3Dtrue%3E`],
  ['deep sel filtered out', `${BASE}/?sel=e-rara:3946379&from=1900&to=1900`],
  ['shared compare pair', `${BASE}/?cmp=e-rara:3946379,e-rara:28588448`],
  ['vv on a record', `${BASE}/?sel=e-rara:3946379&vv=100,100,400,300`],
  ['only whitespace q', `${BASE}/?q=%20%20%20`],
];
const results = [];
for (const [name, url] of cases) {
  results.push(await probe(name, url));
}
console.log(JSON.stringify(results, null, 1));
ws.close();
child.kill('SIGKILL');

