#!/usr/bin/env node
// axe-core accessibility audit of the running app (throwaway, /tmp only).
import { spawn } from 'node:child_process';
import { mkdtemp, readFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';

const BASE = process.argv[2] ?? 'http://127.0.0.1:8787';
const AXE = await readFile('/tmp/a11y/node_modules/axe-core/axe.min.js', 'utf8');
const port = 9445;
const binary = ['/usr/bin/chromium', '/usr/bin/chromium-browser', '/usr/bin/google-chrome'].find(Boolean);
const userDataDir = await mkdtemp(path.join(tmpdir(), 'cdp-axe-'));
const child = spawn(binary, [
  '--headless=new', `--remote-debugging-port=${port}`, `--user-data-dir=${userDataDir}`,
  '--no-sandbox', '--disable-gpu', '--hide-scrollbars', '--window-size=1440,900', 'about:blank',
], { stdio: ['ignore', 'ignore', 'pipe'] });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function endpoint(p) {
  for (let i = 0; i < 40; i += 1) {
    try { const res = await fetch(`http://127.0.0.1:${port}${p}`); if (res.ok) return res.json(); } catch {}
    await sleep(250);
  }
  throw new Error(`CDP ${p} not reachable`);
}
await endpoint('/json/version');
const target = await fetch(`http://127.0.0.1:${port}/json/new?about:blank`, { method: 'PUT' }).then((r) => r.json());
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
let id = 0;
const pending = new Map();
ws.onmessage = (m) => { const d = JSON.parse(m.data); if (d.id && pending.has(d.id)) { pending.get(d.id)(d); pending.delete(d.id); } };
const send = (method, params = {}) => new Promise((resolve) => { const mid = ++id; pending.set(mid, resolve); ws.send(JSON.stringify({ id: mid, method, params })); });
const evalJs = async (expr, awaitPromise = false) => {
  const r = await send('Runtime.evaluate', { expression: expr, returnByValue: true, awaitPromise });
  if (r.result?.exceptionDetails) return { __error: r.result.exceptionDetails.text, detail: r.result.exceptionDetails.exception?.description?.slice(0, 300) };
  return r.result?.result?.value;
};
await send('Runtime.enable');
await send('Page.enable');

async function audit(name, url, prep = '') {
  await send('Page.navigate', { url });
  const t0 = Date.now();
  while (Date.now() - t0 < 20000) {
    const n = await evalJs('document.querySelectorAll("#result-list > *").length');
    if (typeof n === 'number' && n > 0) break;
    await sleep(250);
  }
  await sleep(1200);
  if (prep) { await evalJs(prep); await sleep(800); }
  await evalJs(AXE, false);
  const res = await evalJs(`axe.run(document, { resultTypes: ['violations'] }).then(r => r.violations.map(v => ({
      id: v.id, impact: v.impact, help: v.help, nodes: v.nodes.slice(0, 4).map(n => ({ target: n.target.join(' '), summary: (n.failureSummary||'').split('\\n').slice(0,2).join(' | ').slice(0,180) })),
    })))`, true);
  return { name, url, violations: res };
}

const cases = [
  ['desktop list+map', `${BASE}/`],
  ['desktop time-filtered', `${BASE}/?q=Rhein&from=1600&to=1800`],
  ['detail panel open', `${BASE}/?sel=e-rara:3946379`, `document.querySelector('[data-compare-pin],#detail')`],
  ['compare view', `${BASE}/?cmp=e-rara:8562848,e-rara:8602092`],
  ['about/sources section', `${BASE}/#about`],
];
const out = [];
for (const [name, url, prep] of cases) out.push(await audit(name, url, prep));
console.log(JSON.stringify(out, null, 1));
ws.close();
child.kill('SIGKILL');

